pub(super) fn accuracy_of(id: TranscriptionModelId) -> &'static [BenchmarkRecord] {
    match id {
        TranscriptionModelId::WhisperLargeV3 => WHISPER_LARGE_V3_ACCURACY,
        TranscriptionModelId::WhisperMedium => WHISPER_MEDIUM_ACCURACY,
        TranscriptionModelId::WhisperSmall => WHISPER_SMALL_ACCURACY,
        TranscriptionModelId::BreezeAsr25 => BREEZE_ASR_25_ACCURACY,
        TranscriptionModelId::Qwen3Asr17B => QWEN_1_7B_ACCURACY,
        _ => &[],
    }
}

pub(super) fn speed_of(id: TranscriptionModelId) -> &'static [SpeedRecord] {
    match id {
        TranscriptionModelId::WhisperLargeV3 => WHISPER_LARGE_V3_SPEED,
        TranscriptionModelId::WhisperMedium => WHISPER_MEDIUM_SPEED,
        TranscriptionModelId::WhisperSmall => WHISPER_SMALL_SPEED,
        TranscriptionModelId::BreezeAsr25 => BREEZE_ASR_25_SPEED,
        TranscriptionModelId::Qwen3Asr17B => QWEN_1_7B_SPEED,
        _ => &[],
    }
}
